use vstd::prelude::*;

verus! {
    fn array_to_sequence(arr: &[bool; 10]) -> (res: Vec<bool>)
        requires
            arr.len() == 10, // Ensure the input array has length 10
        ensures
            res.len() == 10, // Ensure the output vector has length 10
            forall|k: nat| (k < 10) ==> (res[k as usize] == arr[k as usize]) // Ensure values are copied correctly
    {
        let mut res: Vec<bool> = Vec::with_capacity(10); // Initialize a vector with capacity 10
        let mut idx: usize = 0; // Initialize index

        while idx < 10
            invariant
                idx <= 10, // Ensure idx does not exceed 10
                res.len() == idx, // Ensure the length of res matches the number of elements copied
                forall|k: nat| (k < idx) ==> (res[k as usize] == arr[k as usize]), // Ensure copied values are correct
            decreases 10 - idx, // Decrease based on remaining iterations
        {
            res.push(arr[idx]); // Copy the value from the array to the vector
            idx = idx + 1; // Increment the index
        }

        res // Return the populated vector
    }
}

